CREATE TABLE IF NOT EXISTS t_p83915249_biotech_anime_store.pirate_fleets (id SERIAL PRIMARY KEY, name TEXT NOT NULL, tier INTEGER NOT NULL DEFAULT 1, ships TEXT NOT NULL DEFAULT '{}', total_attack INTEGER NOT NULL DEFAULT 0, total_defense INTEGER NOT NULL DEFAULT 0, pos_x NUMERIC NOT NULL DEFAULT 400, pos_y NUMERIC NOT NULL DEFAULT 400, home_x NUMERIC NOT NULL DEFAULT 400, home_y NUMERIC NOT NULL DEFAULT 400, status TEXT NOT NULL DEFAULT 'patrol', target_player_id INTEGER, tech_level INTEGER NOT NULL DEFAULT 1, metal_loot INTEGER NOT NULL DEFAULT 0, energy_loot INTEGER NOT NULL DEFAULT 0, crystals_loot INTEGER NOT NULL DEFAULT 0, updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());